create table if not exists maintenance_work_order_comments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),work_order_id uuid not null references maintenance_work_orders(id),user_id uuid,author_email text,comment text not null,created_at timestamptz not null default now());
create table if not exists maintenance_work_order_labor(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),work_order_id uuid not null references maintenance_work_orders(id),user_id uuid,technician_email text,minutes integer not null check(minutes>0),hourly_rate_snapshot numeric(12,2),description text,created_at timestamptz not null default now());
create table if not exists maintenance_attachments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),work_order_id uuid not null references maintenance_work_orders(id),file_name text not null,storage_path text not null,mime_type text,file_size bigint check(file_size>=0),uploaded_by uuid,uploaded_by_email text,created_at timestamptz not null default now());
create index if not exists maintenance_comments_wo_idx on maintenance_work_order_comments(work_order_id,created_at);create index if not exists maintenance_labor_wo_idx on maintenance_work_order_labor(work_order_id,created_at);create index if not exists maintenance_attachments_wo_idx on maintenance_attachments(work_order_id,created_at);
alter table maintenance_work_order_comments enable row level security;alter table maintenance_work_order_labor enable row level security;alter table maintenance_attachments enable row level security;revoke all on maintenance_work_order_comments,maintenance_work_order_labor,maintenance_attachments from anon,authenticated;grant all on maintenance_work_order_comments,maintenance_work_order_labor,maintenance_attachments to service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('maintenance-private','maintenance-private',false,10485760,array['image/jpeg','image/png','image/webp','application/pdf'])on conflict(id)do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;